# The ONLY edits to pre-existing front matter. Exact, uniquely anchored, checked by equality.
# The fourth edits a row an EARLIER trim wrote, resolving its `this commit` (new in kind at the tenth trim).
FRONT_SUBST = (
    ("""**Shards stay write-once.** An eleventh trim writes an eleventh file; it never appends to one of these.
""",
     """**Shards stay write-once.** A twelfth trim writes a twelfth file; it never appends to one of these.
"""),
    ("""**Nothing is bequeathed to the eleventh trim.** The two""",
     """**Nothing is bequeathed to the twelfth trim.** The two"""),
    ("""What these ten trims found, argued and
""",
     """What these eleven trims found, argued and
"""),
    ("""| 10 | S266 `this commit` | 257 → 249 |""",
     """| 10 | S266 `49d23b7` | 257 → 249 |"""),
)


MISSING = object()      # L7/L9/L10/L14: the file is absent from the working tree
NA      = object()      # L7: inapplicable — the trim is not committed yet

ROOT = subprocess.run(["git", "rev-parse", "--show-toplevel"],
                      capture_output=True, text=True, check=True).stdout.strip()


def blob(ref):
    r = subprocess.run(["git", "show", ref], capture_output=True, cwd=ROOT)
    if r.returncode:
        sys.exit("cannot read %s: %s" % (ref, r.stderr.decode("utf-8", "replace").strip()))
    return r.stdout.decode("utf-8")          # bytes -> str; never $(...) which eats trailing newlines


def worktree(rel):
    with open("%s/%s" % (ROOT, rel), encoding="utf-8", newline="") as fh:
        return fh.read()


def added_at(rel):
    """The commit that ADDED `rel`, or "" if git does not know of one."""
    return subprocess.run(["git", "log", "--diff-filter=A", "-1", "--format=%H", "--", rel],
                          capture_output=True, text=True, cwd=ROOT).stdout.strip()


def scan(lines):
    inside = False
    for i, raw in enumerate(lines):
        s = raw.rstrip("\r\n")
        if s.startswith("```") or s.startswith("~~~"):
            yield i, s, inside
            inside = not inside
            continue
        yield i, s, inside


def zones(text):
    """-> (front, [record, ...], lines). A record is a heading-delimited BYTE SPAN, never a session."""
    lines = text.splitlines(keepends=True)
    st = [i for i, s, ins in scan(lines) if not ins and RECORD_START.match(s)]
    if not st:
        return text, [], lines
    front = "".join(lines[:st[0]])
    bounds = st + [len(lines)]
    return front, ["".join(lines[a:b]) for a, b in zip(st, bounds[1:])], lines


def label(rec):
    for ln in rec.splitlines():
        if ln.strip():
            return ln.strip()[:90]
    return "(empty record)"


def ids(recs):
    """The session id captured from each record's own heading line, in order."""
    return tuple(RECORD_START.match(r.splitlines()[0]).group(1) for r in recs)


def declared(before_front, subst=None):
    """The front matter this trim is ALLOWED to produce, before the pointer is inserted."""
    for old, new in (FRONT_SUBST if subst is None else subst):
        before_front = before_front.replace(old, new, 1)
    return before_front


# One canonical clause shape, so all three copies of the table parse with one regex.
ROUTE_CLAUSE = re.compile(r"\*\*(?:(\d+) ≤ N ≤ (\d+)|N ≤ (\d+)|N ≥ (\d+))\*\* → `([^`]+)`")


def parse_table(text):
    out = []
    for a, b, le, ge, dest in ROUTE_CLAUSE.findall(text):
        if a:
            out.append((int(a), int(b), dest))
        elif le:
            out.append((None, int(le), dest))
        else:
            out.append((int(ge), None, dest))
    return tuple(out)


_ID_CACHE = {}


def numeric_ids(dest, after, shard, sha):
    """The numeric session ids actually present in the file `dest` names."""
    if dest == LIVE:
        text = after
    elif dest == SHARD.rsplit("/", 1)[1]:
        text = shard
    else:
        key = (dest, sha)
        if key not in _ID_CACHE:
            path = ARCHIVE_DIR + dest
            try:
                _ID_CACHE[key] = blob("%s:%s" % (sha, path)) if sha else worktree(path)
            except (SystemExit, OSError):
                _ID_CACHE[key] = None
        text = _ID_CACHE[key]
        if text is None:
            return None
    return sorted(int(i) for i in ids(zones(text)[1]) if i.isdigit())


# =====================================================================================
# The assertions. Each returns a list of failure strings; empty == holds.
# =====================================================================================

def L0(name, text):
    """footer_mode='none' asserted: no standalone `---` after the last record start may carry
    content below it. In a newest-on-top ledger the footer sits exactly where an oldest-first cut
    takes from, so 'none' must mean 'I looked', not 'I did not look'."""
    front, recs, lines = zones(text)
    if not recs:
        return ["L0 %s: no records found — grammar mismatch" % name]
    last = [i for i, s, ins in scan(lines) if not ins and RECORD_START.match(s)][-1]
    out = []
    for i, s, ins in scan(lines):
        if not ins and i > last and s.strip() == "---":
            tail = "".join(lines[i + 1:])
            if tail.strip():
                out.append("L0 %s: trailing file-scoped block at line %d (%d B): %.400s"
                           % (name, i + 1, len(tail.encode()), tail))
    return out


def L1(before_recs, after_recs, shard_recs):
    """Concatenation identity scoped to the RECORDS zone. Operand order is load-bearing: this
    ledger is newest-on-top and the cut takes from the bottom, so retained precedes archived. No
    invert step — TRANSFORM is None, which makes this the strongest form. It is ALSO what makes
    L2/b3's records half redundant — the fifth trim's condition, re-checked at this cut."""
    got = "".join(after_recs) + "".join(shard_recs)
    want = "".join(before_recs)
    if got == want:
        return []
    i = next((n for n, (a, b) in enumerate(zip(got, want)) if a != b), min(len(got), len(want)))
    return ["L1: records-zone concatenation differs at character %d "
            "(retained+archived %d B vs before %d B)"
            % (i, len(got.encode()), len(want.encode()))]


# One table row per trim, in the front matter (collapse-on-write, Session 254). TABLE_LINE counts
# rows the way R7 and tests/test_read_budget.py recognise them; TABLE_ROUTE reads the two cells a
# session routes by — the `archived` span and the `shard` name.
TABLE_LINE  = re.compile(r"^\| \d+ \| S\d+ `", re.M)
TABLE_ROUTE = re.compile(r"^\| \d+ \| [^|]+\| (\d+) → (\d+) \| [^|]*\| [^|]*\| `([^`]+)` \|", re.M)


def table_routing(front):
    """The routing the front-matter TABLE states, in ROUTING's shape: one clause per row, oldest
    first, its lower bound open when the row's span starts at Session 1, then the frontier every
    later session falls into (newest archived + 1 -> the live file). Session 254 made the table
    the routing table; this lets L5 hold it against the same declaration as the other two copies."""
    rows = [(None if int(lo) == 1 else int(lo), int(hi), dest)
            for hi, lo, dest in TABLE_ROUTE.findall(front)]
    if rows:
        rows.append((max(hi for _lo, hi, _d in rows) + 1, None, LIVE))
    return tuple(rows)


def defs(text):
    """The assertion names a proof defines, read the way the R-series' R5 reads them."""
    return set(re.findall(r"^def (L\d+)\(", text or "", re.M))


def compose_row(before_front, after_recs, shard_recs, shard, proofs):
    """This trim's table row, COMPOSED from the artifacts and never matched loosely against the
    table. The ordinal follows the rows already there; the trim session is the newest record at
    the trim commit (the R-series' rule); `this commit` is what the legend says the newest row
    carries; `added` is the assertions this proof defines that the tenth proof does not."""
    arch, ret = ids(shard_recs), ids(after_recs)
    added = sorted(defs(proofs[0]) - defs(proofs[1]), key=lambda n: int(n[1:]))
    return ("| %d | S%s `this commit` | %s → %s | %d | %s | `%s` | %s | %s → %s | %s |\n"
            % (len(TABLE_LINE.findall(before_front)) + 1, ret[0], arch[0], arch[-1],
               len(shard_recs), "{:,}".format(len("".join(shard_recs).splitlines())), SHARD_BASE,
               "{:,}".format(len(shard.splitlines())), ret[0], ret[-1],
               ", ".join(added) or "none"))


# ---- L11's stub classifier: a FROZEN copy of tests/test_read_budget.py's `_is_stub` at 3a141ec,
#      with its three patterns. Copied, not imported: the guard may be refined later, and what
#      "non-stub" meant at THIS cut must not move with it. ----
_STUB  = re.compile(r"^\*\*Status:\*\* Session claimed\b")
_FIELD = re.compile(r"^\*\*[^*\n]+:\*\*")
_FENCE = re.compile(r"^(`{3,}|~{3,})")


def is_stub(body):
    """A record with no body, or one whose leading metadata still says the session is claimed."""
    lines = body.split("\n")[1:]
    if not "".join(lines).strip():
        return True
    opens_paragraph, fence = True, ""
    for line in lines:
        if fence:
            if _FENCE.match(line) and set(line.rstrip()) == {fence[0]}:
                fence = ""
            continue
        if not line.strip():
            opens_paragraph = True
            continue
        if opens_paragraph and not _FIELD.match(line):
            return False
        opens_paragraph = False
        opener = _FENCE.match(line)
        if opener:
            fence = opener.group(1)
        elif _STUB.match(line):
            return True
    return False



def L2(before_front, after_front, shard_front, shard_recs, row, subst):
    out = []
    for k, (old, _new) in enumerate(subst, 1):
        if before_front.count(old) != 1:
            out.append("L2/b0 SUBSTITUTION %d NOT UNIQUELY ANCHORED: its source text occurs %d "
                       "times in the before front matter (want exactly 1) — the declaration has "
                       "gone stale against the file it claims to describe" % (k, before_front.count(old)))
    want_front = declared(before_front, subst)
    if row not in after_front:
        out.append("L2_ROW_MISSING: the declared table row is not in the live front matter "
                   "verbatim — a severed record set with no row routing a reader to its shard")
    else:
        residue = after_front.replace(row, "", 1)
        if residue != want_front:
            i = next((n for n, (a, b) in enumerate(zip(residue, want_front)) if a != b),
                     min(len(residue), len(want_front)))
            out.append("L2/b1 CONFINEMENT: live front matter changed beyond the declared row "
                       "insertion + the %d declared substitutions; first divergence at character "
                       "%d (%d B residue vs %d B declared)"
                       % (len(subst), i, len(residue.encode()), len(want_front.encode())))
        # POSITION (added at the ninth trim, on a review's evidence): the residue test cannot see
        # WHERE the row went, and a row outside the table is parsed by every reader of it anyway.
        rows = [ln for ln in want_front.splitlines(keepends=True) if TABLE_LINE.match(ln)]
        if rows and rows[-1] + row not in after_front:
            out.append("L2/position: the declared row is in the front matter but not directly "
                       "below the table's last row — outside the table it is still parsed as "
                       "routing, and nothing else notices")
    after_set = set(after_front.splitlines())
    for ln in want_front.splitlines():
        if ln.strip() and ln not in after_set:      # exact membership, never substring (BL-28)
            out.append("L2/b2 SURVIVAL: front-matter line vanished: %r" % ln[:120])
    # b3 NO-LEAK, narrowed to the BANNER by the fifth trim and carried forward unchanged.
    for ln in before_front.splitlines():
        s = ln.strip()
        if len(s) > 24 and s in shard_front:
            out.append("L2/b3 NO-LEAK: front-matter line leaked into the shard's banner: %r" % s[:120])
    return out



def noleak_note(before_front, shard_recs):
    """NOT an assertion. The lines the pre-narrowing b3 would have flagged in the records half."""
    body = "".join(shard_recs)
    return [(i, ln.strip()) for i, ln in enumerate(before_front.splitlines(), 1)
            if len(ln.strip()) > 24 and ln.strip() in body]


def L3(before_recs, after_recs, shard_recs):
    """Per-record partition by identity, ORDER and byte-equality."""
    have = Counter(after_recs) + Counter(shard_recs)
    before_c = Counter(before_recs)
    absent = list((before_c - have).elements())
    added = list((have - before_c).elements())
    out = []
    for r in absent:
        out.append("L3 MISSING: a record from `before` is in neither artifact "
                   "(dropped, or edited so its original bytes exist nowhere): %s" % label(r))
    for r in added:
        # Project strengthening: this design forbids bundling any record edit into the trim commit
        # (three commits, by rule — claim, trim, close-out), so a non-zero added count means the
        # rule was broken. Deliberate divergence from the canonical tool.
        out.append("L3 ADDED: a record exists that was not in `before` — the trim commit "
                   "bundled a record edit: %s" % label(r))
    if not absent and not added:
        rebuilt, pool = [], Counter(added)
        for r in after_recs + shard_recs:
            if pool[r]:
                pool[r] -= 1
                continue
            rebuilt.append(r)
        bad = [i for i, (a, b) in enumerate(zip(before_recs, rebuilt)) if a != b]
        if bad or len(rebuilt) != len(before_recs):
            out.append("L3 ORDER: records out of order at indices %s" % bad[:12])
    return out


def L4(after_recs, shard_recs):
    """The cut point itself, against the HAND-DECLARED cut key."""
    out = []
    got_a, got_s = ids(after_recs), ids(shard_recs)
    if got_a != CUT_RETAINED:
        out.append("L4 CUT/retained: the live file holds Sessions %s; the declared cut key says %s"
                   % (list(got_a), list(CUT_RETAINED)))
    if got_s != CUT_ARCHIVED:
        out.append("L4 CUT/archived: the shard holds Sessions %s; the declared cut key says %s"
                   % (list(got_s), list(CUT_ARCHIVED)))
    return out


def L5(after_front, shard_front, claude, after, shard, sha, routing):
    """Routing coherence — the sentence a human acts on: which file to open for Session N."""
    out = []
    lo_a, hi_a = min(map(int, CUT_ARCHIVED)), max(map(int, CUT_ARCHIVED))
    lo_r = min(map(int, CUT_RETAINED))
    shard_base = SHARD.rsplit("/", 1)[1]

    for who, got in (("live table", table_routing(after_front)),
                     ("shard banner", parse_table(shard_front)),
                     ("CLAUDE.md", parse_table(claude))):
        if got != routing:
            out.append("L5/1 %s: its routing table parses to %s; the declaration says %s"
                       % (who, list(got), list(routing)))

    below = [c for c in routing if c[0] is None]
    above = [c for c in routing if c[1] is None]
    if len(below) != 1 or len(above) != 1 or routing[0][0] is not None or routing[-1][1] is not None:
        out.append("L5/2 shape: want exactly one open-below clause first and one open-above clause "
                   "last; got %d and %d in %s" % (len(below), len(above), list(routing)))
    else:
        edge = routing[0][1]
        for lo, hi, dest in routing[1:-1]:
            if lo != edge + 1:
                out.append("L5/2 %s at %d-%d (`%s`): the preceding clause ends at %d"
                           % ("GAP" if lo > edge + 1 else "OVERLAP", lo, hi, dest, edge))
            edge = hi
        if routing[-1][0] != edge + 1:
            out.append("L5/2 %s between the last range (ends %d) and `N >= %d` (`%s`)"
                       % ("GAP" if routing[-1][0] > edge + 1 else "OVERLAP", edge,
                          routing[-1][0], routing[-1][2]))

    mine = [c for c in routing if c[2] == shard_base]
    live = [c for c in routing if c[2] == LIVE]
    if len(mine) != 1 or mine[0][:2] != (lo_a, hi_a):
        out.append("L5/3 shard clause: the table routes %s to `%s`; this cut archived Sessions "
                   "%d-%d" % ([c[:2] for c in mine], shard_base, lo_a, hi_a))
    if len(live) != 1 or live[0][:2] != (lo_r, None):
        out.append("L5/3 live clause: the table routes %s to `%s`; this cut retained Sessions "
                   "%d and up" % ([c[:2] for c in live], LIVE, lo_r))

    for lo, hi, dest in routing:
        found = numeric_ids(dest, after, shard, sha)
        if found is None:
            out.append("L5/4 `%s`: the table routes Sessions %s-%s here and the file cannot be "
                       "read" % (dest, lo, hi))
            continue
        if not found:
            out.append("L5/4 `%s`: no numeric session ids found — the check would pass vacuously"
                       % dest)
            continue
        stray = [n for n in found if (lo is not None and n < lo) or (hi is not None and n > hi)]
        if stray:
            out.append("L5/4 `%s`: routed Sessions %s-%s, but it actually contains %s (ids %d-%d)"
                       % (dest, lo, hi, stray[:8], found[0], found[-1]))
    return out


def L6(shard_front, banner):
    """The shard banner, pinned byte-for-byte — the shard-side analogue of L2/b1."""
    if shard_front == banner:
        return []
    i = next((n for n, (a, b) in enumerate(zip(shard_front, banner)) if a != b),
             min(len(shard_front), len(banner)))
    return ["L6 BANNER: the shard's banner is not the declared text; first divergence at character "
            "%d (%d B in the shard vs %d B declared)"
            % (i, len(shard_front.encode()), len(banner.encode()))]


def L7(sha, shard_blob, disk):
    """Write-once, enforced, for THIS shard. Applicability is decided by `disk` ALONE."""
    if disk is NA:
        return []
    if disk is MISSING:
        return ["L7 WRITE-ONCE: the shard is GONE from the working tree. Every assertion above "
                "still passes because they read git history at the trim commit — this one is the "
                "reason you found out."]
    if disk != shard_blob:
        i = next((n for n, (a, b) in enumerate(zip(disk, shard_blob)) if a != b),
                 min(len(disk), len(shard_blob)))
        return ["L7 WRITE-ONCE: the shard on disk is not the shard committed at %s; first "
                "divergence at character %d (%d B on disk vs %d B committed). Shards are "
                "write-once; this file was edited after its trim."
                % (sha[:7] if sha else "the trim commit", i,
                   len(disk.encode()), len(shard_blob.encode()))]
    return []


def L8(reach_texts, routing):
    """The copies that live outside every earlier proof. Both halves matter and neither subsumes
    the other. `routing` is the DECLARED table, taken from the same override L5 reads."""
    out = []
    want_names = {d for _lo, _hi, d in routing if d != LIVE}
    for path, required, forbidden in REACH:
        text = reach_texts.get(path)
        if text is None:
            out.append("L8 `%s`: unreadable, so no copy of the shard set in it can be checked"
                       % path)
            continue
        for s in required:
            if s not in text:
                out.append("L8/required `%s`: this trim declares it must contain %r and it does "
                           "not — the copy no earlier proof could reach is now stale" % (path, s[:90]))
        for s in forbidden:
            if s in text:
                out.append("L8/forbidden `%s`: it still contains %r, which this trim falsified"
                           % (path, s[:90]))
        got_names = set(SHARD_NAME.findall(text))
        if got_names != want_names:
            out.append("L8/set `%s`: it names shards %s; ROUTING names %s (missing %s; unknown %s)"
                       % (path, sorted(got_names), sorted(want_names),
                          sorted(want_names - got_names) or "none",
                          sorted(got_names - want_names) or "none"))
    return out


def L9(lineage):
    """Write-once for the WHOLE lineage. Each ancestor is compared against the blob committed at
    the commit that ADDED it — its own commit, never this trim's."""
    out = []
    for path, committed, disk in lineage:
        if committed is None:
            out.append("L9 `%s`: git knows no commit that added it, so there is nothing to hold "
                       "the working tree against" % path)
            continue
        if disk is MISSING:
            out.append("L9 WRITE-ONCE `%s`: GONE from the working tree. The routing table still "
                       "sends readers here and every byte assertion above still passes, because "
                       "they read history." % path)
            continue
        if disk != committed:
            i = next((n for n, (a, b) in enumerate(zip(disk, committed)) if a != b),
                     min(len(disk), len(committed)))
            out.append("L9 WRITE-ONCE `%s`: on disk it is not the file that was committed; first "
                       "divergence at character %d (%d B on disk vs %d B committed). Shards are "
                       "write-once — this one was edited after its own trim."
                       % (path, i, len(disk.encode()), len(committed.encode())))
    return out


def L10(provenance):
    """The ancestors' PROOFS, held against hand-declared freeze commits. A weakened ancestor proof
    is worse than a deleted one: it still exits 0."""
    out = []
    for path, freeze, committed, disk in provenance:
        if committed is None:
            out.append("L10 `%s`: the declared freeze commit %s does not hold this path, so there "
                       "is nothing to compare the working tree against — the declaration is wrong, "
                       "or the history was rewritten" % (path, freeze[:7]))
            continue
        if disk is MISSING:
            out.append("L10 PROVENANCE `%s`: GONE from the working tree. Its shard is still here "
                       "and L9 still passes on it; its shard's banner and the routing table still tell "
                       "readers to run this proof, and there is nothing left to run." % path)
            continue
        if disk != committed:
            i = next((n for n, (a, b) in enumerate(zip(disk, committed)) if a != b),
                     min(len(disk), len(committed)))
            out.append("L10 PROVENANCE `%s`: on disk it is not the proof frozen at %s; first "
                       "divergence at character %d (%d B on disk vs %d B frozen). An ancestor "
                       "proof was edited after its session ended — if that edit weakened it, it "
                       "still exits 0."
                       % (path, freeze[:7], i, len(disk.encode()), len(committed.encode())))
    return out


def L11(before, after, after_recs, claude, policy):
    """The retention rule this cut exists to satisfy, REWRITTEN at the ninth trim to the byte rule of
    Session 255: fire when the live file exceeds the trigger in BYTES, land at or under the target
    in BYTES, and keep at least the floor in NON-STUB records. L0-L10 ask whether the trim was
    performed faithfully; this asks whether it was performed at all, and not too deep."""
    trigger, target, floor, texts = policy
    out = []
    nb, na = len(before.encode("utf-8")), len(after.encode("utf-8"))
    kept = sum(1 for r in after_recs if not is_stub(r))
    if nb <= trigger:
        out.append("L11/fire: the live file was %s B before this cut; the declared trigger is "
                   "more than %s B, so this trim should not have fired"
                   % ("{:,}".format(nb), "{:,}".format(trigger)))
    if na > target:
        out.append("L11/target: the live file is %s B after this cut; the declared target is at "
                   "most %s B — the cut was too shallow to solve the problem that fired it"
                   % ("{:,}".format(na), "{:,}".format(target)))
    if kept < floor:
        out.append("L11/floor: the live file retains %d non-stub records (%d records in all); the "
                   "declared floor is %d — the cut was too deep and took working context with it"
                   % (kept, len(after_recs), floor))
    for n, s in zip((trigger, target, floor), texts):
        if s not in claude:
            out.append("L11/declared: `CLAUDE.md` no longer states %r, so the numbers this "
                       "assertion enforces are no longer the numbers the project declares" % s[:90])
        elif "{:,}".format(n) not in s:
            out.append("L11/figure: this assertion enforces %s, but the sentence it cites — %r — "
                       "states a different figure. The integer is anchored to nothing, and a trim "
                       "can legitimise a bad cut by typing a new one." % ("{:,}".format(n), s[:90]))
    return out


def L12(before_front, shard_front, shard, after_recs, shard_recs, reach_texts, sizes, prose, row,
        proofs):
    """ARITHMETIC. Every number this trim states about the SIZE of ITS OWN artifacts — and, since
    the pointer block became a table row, every cell of that row."""
    out = []
    measured = {
        "archived_headings": len(shard_recs),
        "archived_lines":    len("".join(shard_recs).splitlines()),
        "shard_total":       len(shard.splitlines()),
        "refuse_bytes":      sizes["refuse_bytes"],
        "mutants":           sizes["mutants"],
    }
    for key in ("archived_headings", "archived_lines", "shard_total"):
        if sizes[key] != measured[key]:
            out.append("L12/%s: this trim declares %s = %d; the artifacts measure %d — a figure "
                       "was typed rather than derived"
                       % (key, key, sizes[key], measured[key]))
    nbytes = len(shard.encode("utf-8"))
    if nbytes > sizes["refuse_bytes"]:
        out.append("L12/cap: the shard is %s B and the declared refusal ceiling is %s B — the "
                   "banner's claim that a default Read returns part of it is false: that Read is "
                   "refused outright and returns nothing"
                   % ("{:,}".format(nbytes), "{:,}".format(sizes["refuse_bytes"])))
    texts = {"shard banner": shard_front}
    texts.update(reach_texts)
    for where, literal, form, keys in prose:
        text = texts.get(where)
        if text is None:
            out.append("L12/prose `%s`: unreadable, so the size figures in it cannot be checked"
                       % where)
            continue
        n = text.count(literal)
        if n == 0:
            out.append("L12/prose `%s`: this trim declares it states %r and it does not — the "
                       "sentence and the artifact have diverged" % (where, literal[:90]))
            continue
        if n > 1:
            out.append("L12/unique `%s`: the declared literal %r occurs %d times, so this arm is "
                       "satisfied by whichever copy it finds and the load-bearing one can go stale "
                       "green. Anchor the literal to the sentence that matters."
                       % (where, literal[:90], n))
            continue
        for key in keys:
            want = WORDS.get(measured[key]) if form == "word" else "{:,}".format(measured[key])
            # Bounded, not substring (ninth trim): "11,681" contains "1,681", "seventeen" "seven".
            bound = (r"\b%s\b" if form == "word" else r"(?<![\d.,])%s(?![\d])") % re.escape(want or "")
            if want is None or not re.search(bound, literal):
                out.append("L12/prose `%s`: %r claims %s but the artifacts measure %s (%r) — the "
                           "prose is stated in a figure nobody derived"
                           % (where, literal[:70], key, measured[key], want))
    if proofs[0] is None:
        out.append("L12/row: this proof cannot be read at the trim commit, so the row's `added` "
                   "cell is held against nothing")
    else:
        want_row = compose_row(before_front, after_recs, shard_recs, shard, proofs)
        if want_row != row:
            out.append("L12/row: this trim declares its table row as %r; composed from the "
                       "artifacts it is %r — a cell was typed rather than derived"
                       % (row.rstrip("\n")[:160], want_row.rstrip("\n")[:160]))
    return out


def L13(after_front, shard_front, reach_texts, after_recs, shard_recs,
        base, form, prose, census):
    """NAME AND SPAN, for THIS cut. The shard's own FILENAME, and every sentence stating which
    sessions moved, held against the record ids actually present in the two files.

    The two spans the table row states are L12/row's, which composes the whole row. The CENSUS
    sentence lives in the shard banner since the ninth trim — collapse-on-write leaves prose no
    home in the front matter — and the eighth trim's uniqueness arm is kept: count == 1, never
    membership."""
    out = []
    arch, ret = ids(shard_recs), ids(after_recs)
    if not arch or not ret:
        return ["L13: a records zone is empty — there is no span to derive"]
    spans = {"archived": (arch[0], arch[-1]), "retained": (ret[0], ret[-1])}
    want_name = form % spans["archived"]
    if base != want_name:
        out.append("L13/name: this trim names its shard `%s`, but the records inside it are "
                   "Sessions %s-%s, which the naming rule makes `%s`. A filename is the first "
                   "routing information a reader sees and it disagrees with the file."
                   % (base, spans["archived"][0], spans["archived"][1], want_name))
    texts = {"shard banner": shard_front}
    texts.update(reach_texts)
    for where, literal, sep, which in prose:
        text = texts.get(where)
        if text is None:
            out.append("L13/prose `%s`: unreadable, so the span sentences in it cannot be checked"
                       % where)
            continue
        n = text.count(literal)
        if n == 0:
            out.append("L13/prose `%s`: this trim declares it states %r and it does not — the "
                       "sentence and the artifact have diverged" % (where, literal[:90]))
            continue
        if n > 1:
            out.append("L13/unique `%s`: the declared literal %r occurs %d times, so a stale copy "
                       "of the span can satisfy this arm while the sentence that matters is wrong"
                       % (where, literal[:90], n))
            continue
        want = "%s%s%s" % (spans[which][0], sep, spans[which][1])
        if not re.search(r"(?<![\d.,])%s(?![\d])" % re.escape(want), literal):
            out.append("L13/span `%s`: %r states an %s span that the records do not have; they "
                       "measure %r — a span was typed rather than derived"
                       % (where, literal[:70], which, want))
    c = shard_front.count(census)
    if c == 0:
        out.append("L13/census-absent: the shard banner no longer states %r, so the count a "
                   "reader trusts about this assertion's reach is not in the file at all"
                   % census[:90])
    elif c > 1:
        out.append("L13/census-unique: %r occurs %d times in the shard banner, so this arm is "
                   "satisfied by whichever copy it finds" % (census[:90], c))
    else:
        want = WORDS.get(len(prose))
        if want is None or not census.startswith("**%s " % want):
            out.append("L13/census: the banner tells a reader L13 holds %r, but it reads "
                       "%d sentence(s) — that count was typed, not derived"
                       % (census[:90], len(prose)))
    return out


def L14(shard_front, reach_texts, lineage, routing, prose, census):
    """LINEAGE FIGURES. Every ANCESTOR shard's span and size figure, in the four files L8 reaches.

    L12 and L13 are scoped to the cut that ships them BY CONSTRUCTION — they measure the two files
    in hand. So the moment the next trim lands, the shard they guarded becomes an ancestor and its
    figures fall out of every assertion's reach permanently. Seven trims' worth had accumulated.

    Three halves, and none can satisfy another. The SET half holds the shards the declared literals
    are about against ROUTING's ancestor set — that is the arm that stops the NEXT trim reopening
    this, because it cannot inherit this declaration unchanged and be green. The PROSE half derives
    each figure from the ancestor shard AT ITS OWN ADD-COMMIT (never the working tree: L9 proves
    disk == add-commit, so reading disk would make L14 silently depend on L9) and holds it against
    the literal. The CENSUS arm holds this assertion's claim about its own reach against what it
    actually reads, and — like L13's — asserts that claim occurs exactly once."""
    out = []
    # measure every ancestor from its own add-commit blob
    facts = {}
    for path, committed, _disk in lineage:
        base = path.rsplit("/", 1)[1]
        if committed is None:
            continue                       # unmeasurable; the blob arm below reports it
        recs = zones(committed)[1]
        if not recs:
            continue
        i = ids(recs)
        facts[base] = {"span": (i[0], i[-1]),
                       "total": len(committed.splitlines()),
                       "record_lines": len("".join(recs).splitlines())}

    want_shards = {d for _lo, _hi, d in routing
                   if d != LIVE and d != SHARD.rsplit("/", 1)[1]}
    got_shards = {s for _w, _l, _sep, pairs in prose for s, _f in pairs}
    if got_shards != want_shards:
        out.append("L14/set: the declared literals are about shards %s; ROUTING's ancestor set is "
                   "%s (missing %s; unknown %s). A shard whose figures no literal here mentions is "
                   "described by prose nothing derives — which is the whole hole this assertion "
                   "closes, reopened."
                   % (sorted(got_shards), sorted(want_shards),
                      sorted(want_shards - got_shards) or "none",
                      sorted(got_shards - want_shards) or "none"))

    texts = dict(reach_texts)
    for where, literal, sep, pairs in prose:
        text = texts.get(where)
        if text is None:
            out.append("L14/prose-unreadable `%s`: unreadable, so the ancestor figures in it "
                       "cannot be checked" % where)
            continue
        n = text.count(literal)
        if n == 0:
            out.append("L14/prose `%s`: this trim declares it states %r and it does not — the "
                       "sentence and the ancestor it describes have diverged"
                       % (where, literal[:90]))
            continue
        if n > 1:
            out.append("L14/unique `%s`: the declared literal %r occurs %d times, so a stale copy "
                       "can satisfy this arm while the load-bearing one is wrong"
                       % (where, literal[:90], n))
            continue
        for base, field in pairs:
            f = facts.get(base)
            if f is None:
                # Covers both "git knows no add-commit for it" and "the declaration names a shard
                # the lineage does not contain". Reported, never skipped: a figure held against
                # nothing is the state this assertion exists to end.
                out.append("L14/blob `%s`: `%s` cannot be measured at its own add-commit, so the "
                           "figure %r states about it is held against nothing"
                           % (where, base, literal[:60]))
                continue
            if field == "span":
                want = "%s%s%s" % (f["span"][0], sep, f["span"][1])
            else:
                want = "{:,}".format(f[field])
            if not re.search(r"(?<![\d.,])%s(?![\d])" % re.escape(want), literal):
                out.append("L14/%s `%s`: %r states a %s for `%s` that the shard does not have; "
                           "measured at its own add-commit it is %r — an ancestor figure was "
                           "typed rather than derived"
                           % ("span" if field == "span" else "size",
                              where, literal[:70], field, base, want))
    # COMPLETENESS. Every arm above checks a literal the trim DECLARED. This one checks that the
    # declaration is not MISSING one: it scans each text for every ancestor's span and size figure
    # and requires each occurrence to fall inside a declared literal. Without it, L14 proves only
    # that the figures someone chose to list are right — which is exactly how the seventh trim's
    # bequest came to under-count its own subject, and how the eighth trim's first draft shipped 44
    # declared against 45 present. Learning #126 ("the list was written by someone who had not run
    # it") mechanised, one field at a time.
    for where in sorted(texts):
        text = texts[where]
        if text is None:
            continue                       # already reported by the unreadable arm above
        covered = []
        for _w, lit, _s, _p in prose:
            if _w != where:
                continue
            i = 0
            while True:
                j = text.find(lit, i)
                if j < 0:
                    break
                covered.append((j, j + len(lit)))
                i = j + 1
        for base in sorted(facts):
            f = facts[base]
            pats = [(re.escape("%s%s%s" % (f["span"][0], s, f["span"][1])), "span")
                    for s in ("→", "->")]
            pats += [(re.escape("{:,}".format(f[k])), k) for k in ("total", "record_lines")]
            for pat, kind in pats:
                for m in re.finditer(r"(?<![\d.,])%s(?![\d])" % pat, text):
                    if any(a <= m.start() and m.end() <= b for a, b in covered):
                        continue
                    out.append("L14/complete `%s`: at character %d it states `%s`'s %s (%r) "
                               "outside every declared literal — an ancestor figure the "
                               "declaration does not reach, which is the defect this assertion "
                               "exists to end: ...%s..."
                               % (where, m.start(), base, kind, m.group(0),
                                  text[max(0, m.start() - 40):m.end() + 25].replace("\n", " ")))
    c = shard_front.count(census)
    if c == 0:
        out.append("L14/census-absent: the shard banner no longer states %r, so the count a "
                   "reader trusts about this assertion's reach is not in the file at all"
                   % census[:90])
    elif c > 1:
        out.append("L14/census-unique: %r occurs %d times in the shard banner, so this arm is "
                   "satisfied by whichever copy it finds" % (census[:90], c))
    else:
        figures = sum(len(pairs) for _w, _l, _s, pairs in prose)
        got = re.fullmatch(r"\*\*(\d+) declared literals\*\* carrying \*\*(\d+) figures\*\*", census)
        for n_, what, g in ((len(prose), "literals", 1), (figures, "figures", 2)):
            if not got or int(got.group(g)) != n_:
                out.append("L14/census: the banner tells a reader L14 holds %r, but it "
                           "reads %d %s — that count was typed, not derived"
                           % (census[:90], n_, what))
    return out


def check(before, after, shard, claude, sha, disk, reach_texts, lineage, provenance, proofs,
          decl=None):
    d = {"ROW": ROW, "BANNER": BANNER, "ROUTING": ROUTING, "POLICY": POLICY,
         "SIZES": SIZES, "SIZE_PROSE": SIZE_PROSE, "SHARD_BASE": SHARD_BASE,
         "NAME_FORM": NAME_FORM, "SPAN_PROSE": SPAN_PROSE, "SPAN_CENSUS": SPAN_CENSUS,
         "FRONT_SUBST": FRONT_SUBST, "LINEAGE_PROSE": LINEAGE_PROSE,
         "LINEAGE_CENSUS": LINEAGE_CENSUS}
    if decl:
        d.update(decl)
    proofs = d.get("PROOFS", proofs)
    bf, br, _ = zones(before)
    af, ar, _ = zones(after)
    sf, sr, _ = zones(shard)
    fails = []
    fails += L0("before", before) + L0("after", after) + L0("shard", shard)
    fails += L1(br, ar, sr)
    fails += L2(bf, af, sf, sr, d["ROW"], d["FRONT_SUBST"])
    fails += L3(br, ar, sr)
    fails += L4(ar, sr)
    fails += L5(af, sf, claude, after, shard, sha, d["ROUTING"])
    fails += L6(sf, d["BANNER"])
    fails += L7(sha, shard, disk)
    fails += L8(reach_texts, d["ROUTING"])
    fails += L9(lineage)
    fails += L10(provenance)
    fails += L11(before, after, ar, claude, d["POLICY"])
    fails += L12(bf, sf, shard, ar, sr, reach_texts, d["SIZES"], d["SIZE_PROSE"], d["ROW"], proofs)  # one line on purpose: the neuter loop replaces it with `pass`
    fails += L13(af, sf, reach_texts, ar, sr, d["SHARD_BASE"], d["NAME_FORM"], d["SPAN_PROSE"], d["SPAN_CENSUS"])  # one line on purpose
    fails += L14(sf, reach_texts, lineage, d["ROUTING"], d["LINEAGE_PROSE"], d["LINEAGE_CENSUS"])
    return fails, (br, ar, sr)


def artifacts():
    sha = added_at(SHARD)

    # L9's and L14's operands never depend on `sha`: each ancestor is held against ITS OWN
    # add-commit, so both are applicable before this trim is committed at all.
    lineage = []
    for path in ANCESTORS:
        a = added_at(path)
        committed = blob("%s:%s" % (a, path)) if a else None
        try:
            on_disk = worktree(path)
        except OSError:
            on_disk = MISSING
        lineage.append((path, committed, on_disk))
    lineage = tuple(lineage)

    # L10's operands never depend on `sha` either: each ancestor proof is held against its own
    # HAND-DECLARED freeze commit.
    provenance = []
    for path, freeze in ANCESTOR_PROOFS:
        try:
            committed = blob("%s:%s" % (freeze, path))
        except SystemExit:
            committed = None
        try:
            on_disk = worktree(path)
        except OSError:
            on_disk = MISSING
        provenance.append((path, freeze, committed, on_disk))
    provenance = tuple(provenance)

    # L12/row's `added` cell: the assertions THIS proof defines, as committed with the shard, less
    # those the tenth proof defines at its freeze commit. Before the commit, this file on disk.
    try:
        this = blob("%s:%s" % (sha, PROOF)) if sha else worktree(PROOF)
    except (SystemExit, OSError):
        this = None
    proofs = (this, provenance[-1][2])

    if sha:
        try:
            disk = worktree(SHARD)
        except OSError:
            disk = MISSING
        reach = {}
        for p, _r, _f in REACH:
            try:                                  # so L8's unreadable arm is live code, not dead
                reach[p] = blob("%s:%s" % (sha, p))
            except SystemExit:
                reach[p] = None
        return (blob("%s^:%s" % (sha, LIVE)), blob("%s:%s" % (sha, LIVE)),
                blob("%s:%s" % (sha, SHARD)), blob("%s:%s" % (sha, CLAUDE)),
                "the trim commit %s" % sha[:7], sha, disk, reach, lineage, provenance, proofs)
    reach = {}
    for p, _r, _f in REACH:
        try:
            reach[p] = worktree(p)
        except OSError:
            reach[p] = None
    return (blob("HEAD:%s" % LIVE), worktree(LIVE), worktree(SHARD), worktree(CLAUDE),
            "HEAD vs the working tree (trim not yet committed)", None, NA, reach, lineage,
            provenance, proofs)


def self_test(before, after, shard, claude, sha, reach, lineage, provenance, proofs):
    _, ar, _ = zones(after)
    sf, sr, _ = zones(shard)
    body = "".join(sr)
    assert sf == BANNER, "self-test needs a green L6: the shard's banner must be the declared text"
    purpose = next(ln for ln in zones(before)[0].splitlines() if ln.startswith("**Purpose:**"))

    def sub_in_shard(o, n, count=1):
        assert o in shard, "self-test fixture missing: %r" % o[:40]
        return shard.replace(o, n, count)

    def banner_only(pairs):
        """Rewrite the banner in the DECLARATION and the ARTIFACT together, so L6 is satisfied. The
        shard is rebuilt as that banner plus the untouched records, never edited in place: a
        record may quote the same text, and a whole-file replace would mutate it too."""
        b = BANNER
        for o, n in pairs:
            assert b.count(o) == 1, "banner fixture occurs %d times: %r" % (b.count(o), o[:50])
            b = b.replace(o, n, 1)
        return b, b + body

    def clauses(pairs):
        """The same routing-clause rewrites in the banner (declaration and artifact) and CLAUDE.md."""
        b, c = BANNER, claude
        for o, n in pairs:
            assert b.count(o) == 1 and c.count(o) == 1, "clause fixture: %r" % o[:40]
            b, c = b.replace(o, n, 1), c.replace(o, n, 1)
        return b, b + body, c

    def table_with(pairs):
        """Rewrite rows 1-8 of the table in BOTH `before` and `after`. Those rows sit in the
        pre-trim front matter, so L2 stays satisfied and only a routing copy can object."""
        b, a = before, after
        for o, n in pairs:
            assert b.count(o) == 1 and a.count(o) == 1, "table fixture: %r" % o[:50]
            b, a = b.replace(o, n, 1), a.replace(o, n, 1)
        return b, a

    def row_and_after(o, n):
        """Rewrite this trim's ROW in the declaration AND the live file, so L2 is satisfied."""
        assert ROW.count(o) == 1 and after.count(ROW) == 1, "row fixture: %r" % o
        new = ROW.replace(o, n, 1)
        return new, after.replace(ROW, new, 1)

    assert "−" in body, "self-test fixture missing: no U+2212 in the archived span"
    assert "−" not in sf, "fixture broken: M9 must mutate a RECORD, not the shard banner"

    # M13's fixture: a front-matter sentence that is NOT the row and NOT touched by any declared
    # substitution, so mutating it is a genuinely UNDECLARED front-matter edit.
    UNDECL = "That is this apparatus's largest hole, it is measured rather than suspected"
    assert after.count(UNDECL) == 1 and UNDECL not in ROW, "M13 fixture broken"
    for _o, n in FRONT_SUBST:
        assert UNDECL not in n, "M13 fixture broken: it sits inside a declared substitution"

    # M98-M100 isolate three L2 arms the per-arm sweep found reachable only in company.
    # M98 — L2/b0 alone: substitution 1's anchor DUPLICATED in `before`, the copy left unreplaced in
    # `after` beside the replacement. declared() replaces the first occurrence only, so the residue
    # still matches and only the uniqueness arm can object.
    FS0_OLD, FS0_NEW = FRONT_SUBST[0]
    assert before.count(FS0_OLD) == 1 and after.count(FS0_NEW) == 1, "M98 fixture broken"
    m98_bf = before.replace(FS0_OLD, FS0_OLD + FS0_OLD, 1)
    m98_a = after.replace(FS0_NEW, FS0_NEW + FS0_OLD, 1)
    # M99 — L2_ROW_MISSING alone: the row edited in the live file only (one space), so the declared
