    # M105 — L2/position alone: the row moved below the table, text intact. The residue still
    # matches and every reader of the table still parses it, which is the hole the arm closes.
    ANCHOR105 = "\n---\n\n## ACTIVE TASK\n"
    assert after.count(ANCHOR105) == 1, "M105 fixture broken"
