before, after, shard, claude, source, sha, disk, reach, lineage, provenance, proofs = artifacts()

if "--self-test" in sys.argv:
    print("--self-test: mutating the artifacts and asserting each mutation is caught.\n")
    self_test(before, after, shard, claude, sha, reach, lineage, provenance, proofs)
    sys.exit(0)

fails, (br, ar, sr) = check(before, after, shard, claude, sha, disk, reach, lineage, provenance,
                            proofs)
have = Counter(ar) + Counter(sr)
added = len(list((have - Counter(br)).elements()))
note = noleak_note(zones(before)[0], sr)
kept = sum(1 for r in ar if not is_stub(r))

print("source : %s" % source)
print("grammar: heading /^### What Session \\S+ Did$/ ; footer_mode=none (asserted) ; transform=none")
print("records: %d before = %d retained + %d archived; added by the trim commit: %d"
      % (len(br), len(ar), len(sr), added))
print("cut key: retained %s | archived %s   (hand-declared, checked by L4 and L5)"
      % (list(CUT_RETAINED), list(CUT_ARCHIVED)))
print("routing: %d clauses, checked in 3 copies (the front-matter table, the shard banner,"
      % len(ROUTING))
print("         CLAUDE.md) and anchored against the record ids actually in each file it names")
print("reach  : %d copies L5 does not check (%s)"
      % (len(REACH), ", ".join(p for p, _r, _f in REACH)))
print("lineage: %d ancestor shard(s) held against their own add-commits" % len(lineage))
print("provena: %d ancestor proof(s) held against hand-declared freeze commits" % len(provenance))
print("policy : fired above %s B at %s B; landed at %s B (target %s B); kept %d non-stub records"
      % ("{:,}".format(POLICY[0]), "{:,}".format(len(before.encode("utf-8"))),
         "{:,}".format(len(after.encode("utf-8"))), "{:,}".format(POLICY[1]), kept))
print("         of %d in all (floor %d) — the byte rule, as the ninth trim rewrote it" % (len(ar), POLICY[2]))
print("size   : %d archived headings, %d archived lines, shard %d lines / %s B (refused above %s B)"
      % (len(sr), len("".join(sr).splitlines()), len(shard.splitlines()),
         "{:,}".format(len(shard.encode("utf-8"))), "{:,}".format(SIZES["refuse_bytes"])))
print("         — measured here, held against %d declared integers, %d prose claims in %d texts,"
      % (len(SIZES), len(SIZE_PROSE), len({w for w, _l, _f, _k in SIZE_PROSE})))
print("         and this trim's table row, composed cell by cell from the artifacts")
print("span   : archived %s → %s, retained %s → %s — derived from the record ids, held against the"
      % (ids(sr)[0], ids(sr)[-1], ids(ar)[0], ids(ar)[-1]))
print("         shard's own FILENAME (`%s`) and %d sentence(s) in %d texts"
      % (SHARD_BASE, len(SPAN_PROSE), len({w for w, _l, _s, _k in SPAN_PROSE})))
print("lineage figures: %d literals carrying %d figures, over %d ancestor shard(s) in %d texts —"
      % (len(LINEAGE_PROSE), sum(len(p) for _w, _l, _s, p in LINEAGE_PROSE),
         len({b for _w, _l, _s, pr in LINEAGE_PROSE for b, _f in pr}),
         len({w for w, _l, _s, _p in LINEAGE_PROSE})))
print("         each measured from that shard's OWN add-commit blob, never the working tree")
print("front  : one table row inserted + %d declared substitutions, all checked by exact equality"
      % len(FRONT_SUBST))
print("checked: L0, L1, L2/front-matter, L3, L4, L5, L6, L7, L8, L9, L10, L11, L12, L13, L14    "
      "<- L2/footer absent: inapplicable, no footer zone")
print("b3 note: narrowed to the banner at the FIFTH trim; its condition (TRANSFORM is None, L1")
print("         present) re-checked here and still holds. %d front-matter line(s) occur inside the"
      % len(note))
print("         archived RECORDS and would have been flagged by the pre-narrowing predicate.")
if any(f.startswith("L1:") for f in fails):
    print("         *** L1 IS RED ON THIS RUN. These lines are NOT pinned, so the half the fifth")
    print("         *** trim narrowed away would have carried information here. Treat each as a")
    print("         *** CANDIDATE LEAK until L1 is green again.")
else:
    print("         L1 is green, so each is pinned byte-for-byte and none of them can be a leak.")
print("         Nothing is hidden:")
for i, s in note:
    print("           front-matter line %d: %s" % (i, s[:120]))
if not note:
    print("           (none on this cut)")
if sha is None:
    print("         L7 inapplicable: the trim is not committed yet, so there is no frozen blob to")
    print("         compare the working tree against. It becomes live at the trim commit. L9, L10,")
    print("         L12, L13 and L14 are applicable already.")

if fails:
    print("\nFAIL for %s:" % SHARD)
    for f in fails:
        print("  " + f)
    sys.exit(1)

print("\nOK: %s hold for %s" % ("L0-L14" if sha else "L0-L6, L8-L14 (L7 inapplicable)", SHARD))
print("    Every byte of the pre-trim records zone is still present, in the right file, unedited,")
print("    in order, and on the declared side of the declared boundary; all three copies of the")
print("    routing table agree with that boundary AND with what the files they name contain; the")
print("    front matter changed by one table row and the declared substitutions only, and that row")
print("    was composed from the artifacts; the shard's banner is the declared text and carries no")
print("    leaked front matter; README.md, PROJECT_CONVENTIONS.md, BACKLOG.md and CLAUDE.md describe")
print("    the shard set that now exists; every earlier shard AND every earlier proof on disk is")
print("    still the file its own session froze; this cut obeyed the byte rule CLAUDE.md declares;")
print("    every size figure any of those files states was derived rather than typed; the shard's")
print("    own FILENAME, plus every sentence naming the sessions that moved, matches the record ids")
print("    the two files contain; and every figure those four files state about an EARLIER shard")
print("    was derived from that shard at its own add-commit.")
if sha:
    print("    The shard on disk is still the shard that was committed at %s." % sha[:7])
else:
    print("    NOTHING is claimed about THIS shard on disk: L7 has no frozen blob to compare it")
    print("    against until the trim is committed. Re-run after committing.")
print("    It says NOTHING about whether the boundary was wisely chosen BEYOND the three numbers")
print("    L11 enforces, nor whether any record's content is true — a human reads that once. It")
print("    does not re-prove the ten earlier cuts, and it does not check the front-matter table's")
print("    other rows: the collapse proofs own those. Run them all. A green proof never")
print("    --self-test'ed proves less than it appears to.")
PYEOF
